function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 10000) return 'mat needs 1 to 10^4 rows.';
  const n = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (n < 1 || n > 10000) return 'Each row needs 1 to 10^4 values.';
  if (mat.length * n > 10000) return 'mat can hold at most 10^4 cells.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is an integer between -10^5 and 10^5.';
  }
  return null;
}

