function findDiagonalOrder(mat) {
  const groups = [];
  for (let r = 0; r < mat.length; r++) {
    for (let c = 0; c < mat[r].length; c++) {
      if (!groups[r + c]) groups[r + c] = [];
      groups[r + c].push(mat[r][c]);
    }
  }
  const out = [];
  groups.forEach((group, sum) => {
    const ordered = sum % 2 === 0 ? group.slice().reverse() : group;
    for (const v of ordered) out.push(v);
  });
  return out;
}

