function generate(rand, size) {
  const value = (span) => {
    const pick = rand();
    if (pick < 0.05) return 100000;
    if (pick < 0.1) return -100000;
    return Math.floor(rand() * (2 * span + 1)) - span;
  };
  const build = (m, n, span) => Array.from({ length: m }, () => Array.from({ length: n }, () => value(span)));
  if (size === 'large') {
    const shape = rand();
    if (shape < 0.25) return [build(100, 100, 100000)];
    if (shape < 0.4) return [build(1, 2000, 100000)];
    if (shape < 0.55) return [build(2000, 1, 100000)];
    if (shape < 0.7) return [build(5, 2000, 100000)];
    const m = 1 + Math.floor(rand() * 100);
    const n = 1 + Math.floor(rand() * 100);
    return [build(m, n, 100000)];
  }
  const m = 1 + Math.floor(rand() * 5);
  const n = 1 + Math.floor(rand() * 5);
  return [build(m, n, 9)];
}
